// intro screen where top button selects english and bottom selects tagalog
#include "./language_selection.h"
#include <ti/devices/msp/msp.h>
#include <stdint.h>
#include "../inc/LaunchPad.h"


// pb16 selects english
// pb17 selects tagalog
uint32_t language_flag; // 0 = button 1 (PB16), 1 = button 2 (PB17)

void Buttons_Init(void) {
    uint32_t In = 0x00040081; // input with pull-down (same as Lab 4)
    IOMUX->SECCFG.PINCM[PB16INDEX] = In;
    IOMUX->SECCFG.PINCM[PB17INDEX] = In;
    // DOE not set for these pins since they are inputs
}

void WaitForButtonPress(void) {
    while (1) {
        uint32_t data = GPIOB->DIN31_0;
        if (data & (1 << 16)) {       // PB15 pressed
            while (GPIOB->DIN31_0 & (1 << 16)) {} // wait for release
            language_flag = 0;
            return;
        }
        if (data & (1 << 17)) {       // PB16 pressed
            while (GPIOB->DIN31_0 & (1 << 17)) {} // wait for release
            language_flag = 1;
            return;
        }
    }
}

